[InitializeOnLoad] public static class ValidacaoPolimentoGlobal {
 const BindingFlags Flags=BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;
 [Serializable] class Setup {public SceneSetup[] scenes;}
 static ValidacaoPolimentoGlobal(){EditorApplication.playModeStateChanged+=s=>{
  if(s==PlayModeStateChange.EnteredPlayMode&&SessionState.GetBool("Polimento.Start",false)){SessionState.SetBool("Polimento.Start",false);new GameObject("TestesPolimentoDirecionados").AddComponent<ChecksPolimentoGlobal>();}
  if(s==PlayModeStateChange.EnteredEditMode&&SessionState.GetBool("Polimento.End",false)){
   SessionState.SetBool("Polimento.End",false);SessionState.SetBool("NexaQuest.ValidandoQuiz",false);
   if(SessionState.GetInt("Polimento.Phase",1)==1&&SessionState.GetBool("Polimento.Pass",false)){SessionState.SetInt("Polimento.Phase",2);EditorApplication.delayCall+=Iniciar;return;}
   if(SessionState.GetBool("Polimento.VolumeExists",false))PlayerPrefs.SetFloat(NexaAudioManager.VolumeKey,SessionState.GetFloat("Polimento.Volume",1));else PlayerPrefs.DeleteKey(NexaAudioManager.VolumeKey);PlayerPrefs.Save();
   bool real=SessionState.GetString("Polimento.Real","")==PlayerPrefs.GetString(ProgressionManager.ChavePersistencia,"");File.WriteAllText(MontagemPolimentoGlobal.Docs+"progresso-real.txt","Progresso real preservado: "+real);
   typeof(QuestHUDVisualValidation).GetMethod("RestoreGameView",Flags).Invoke(null,null);var setup=JsonUtility.FromJson<Setup>(SessionState.GetString("Polimento.Setup",""));EditorSceneManager.RestoreSceneManagerSetup(setup.scenes);
   object[] counts={0,0,0};typeof(Editor).Assembly.GetType("UnityEditor.LogEntries").GetMethod("GetCountsByType",Flags).Invoke(null,counts);
   File.WriteAllText(MontagemPolimentoGlobal.Docs+"console.txt","Erros: "+counts[0]+"\nAvisos: "+counts[1]+"\nMensagens: "+counts[2]+"\n"+DateTime.Now.ToString("s"));File.WriteAllText(MontagemPolimentoGlobal.Docs+"estado-editor.txt",SceneManager.GetActiveScene().path+"\nDirty: "+SceneManager.GetActiveScene().isDirty+"\nPlay Mode: "+EditorApplication.isPlaying);
  }
 };}
 public static void Executar(){
  if(EditorSceneManager.GetSceneManagerSetup().Any(s=>SceneManager.GetSceneByPath(s.path).isDirty))throw new InvalidOperationException("Salve as cenas antes dos testes.");
  SessionState.SetString("Polimento.Setup",JsonUtility.ToJson(new Setup{scenes=EditorSceneManager.GetSceneManagerSetup()}));SessionState.SetBool("Polimento.VolumeExists",PlayerPrefs.HasKey(NexaAudioManager.VolumeKey));SessionState.SetFloat("Polimento.Volume",PlayerPrefs.GetFloat(NexaAudioManager.VolumeKey,1));SessionState.SetString("Polimento.Real",PlayerPrefs.GetString(ProgressionManager.ChavePersistencia,""));SessionState.SetInt("Polimento.Phase",1);Iniciar();
 }
 static void Iniciar(){
  EditorSceneManager.OpenScene("Assets/Projeto/Scenes/Menu.unity");typeof(QuestHUDVisualValidation).GetMethod("SetGameView",Flags).Invoke(null,null);
  if(SessionState.GetInt("Polimento.Phase",1)==1)typeof(Editor).Assembly.GetType("UnityEditor.LogEntries").GetMethod("Clear",Flags).Invoke(null,null);
  SessionState.SetBool("NexaQuest.ValidandoQuiz",true);PlayerPrefs.SetString("NexaQuest.Testes.Quiz","{\"versao\":1,\"energia\":100,\"coins\":0,\"level\":1,\"currentXP\":0}");PlayerPrefs.Save();SessionState.SetBool("Polimento.Start",true);SessionState.SetBool("Polimento.End",true);EditorApplication.isPlaying=true;
 }
}
