 IEnumerator CheckSettingsDetails(){
  Time.timeScale=.65f;pause.Open();yield return null;
  var slider=pause.volume;var bg=slider.transform.Find("Background").gameObject;var point=slider.handleRect.parent.TransformPoint(new Vector3(-107.5f,0,0));
