  C(Mathf.Abs(slider.value-.25f)<.02f&&Mathf.Abs(audio.MasterVolume-slider.value)<.001f,"Clique real na barra altera Slider e Master");
  data.position=slider.handleRect.parent.TransformPoint(new Vector3(107.5f,0,0));ExecuteEvents.Execute(slider.gameObject,data,ExecuteEvents.dragHandler);
  C(Mathf.Abs(slider.value-.75f)<.02f,"Arrastar real do Slider altera volume");
  C(Mathf.Abs(slider.handleRect.rect.height-42)<.1f,"Handle com altura correta de 42 pixels");
  pause.Close();C(Mathf.Abs(Time.timeScale-.65f)<.001f,"Voltar restaura TimeScale anterior diferente de um");Time.timeScale=1;audio.SetMasterVolume(.37f);
  SceneManager.LoadScene("Brasil");yield return SceneReady("Brasil");var w=FindObjectOfType<BrazilWorld>();w.player.SetControlsLocked(true);pause.Open();pause.Close();C(w.player.ControlsLocked,"Pausa preserva bloqueio anterior de controles");w.player.SetControlsLocked(false);yield return null;
  var pa=FindObjectOfType<PainelDesafiosAmazonia>(true);var ma=FindObjectOfType<MinijogoAmazoniaController>(true);
